-- Reconcile the stored balance with the ledger. Safe to re-run.
UPDATE escrow_payment e
LEFT JOIN (
  SELECT escrow_id, SUM(amount) AS settled
  FROM monthly_payout_log
  WHERE payout_status = 'SETTLED'
  GROUP BY escrow_id
) p ON p.escrow_id = e.escrow_id
SET e.released_amount  = COALESCE(p.settled, 0),
    e.remaining_amount = e.total_prepaid - COALESCE(p.settled, 0),
    e.escrow_status    = CASE
                           WHEN COALESCE(p.settled, 0) >= e.total_prepaid THEN 'RELEASED'
                           WHEN COALESCE(p.settled, 0) > 0 THEN 'PARTIAL'
                           ELSE 'HELD'
                         END;

-- Groups under a live dispute freeze the remaining balance.
UPDATE escrow_payment e
JOIN membership_seat s ON s.seat_id = e.seat_id
JOIN carpool_group  g ON g.group_id = s.group_id
SET e.escrow_status = 'FROZEN'
WHERE g.status = 'FROZEN' AND e.escrow_status IN ('HELD','PARTIAL');

-- Seats whose dispute ended in a refund are marked as returned.
UPDATE escrow_payment e
JOIN membership_seat s ON s.seat_id = e.seat_id
JOIN dispute d        ON d.seat_id = s.seat_id
SET e.escrow_status = 'REFUNDED', s.seat_status = 'REFUNDED'
WHERE d.dispute_status = 'REFUNDED';

-- Repair two cross-table inconsistencies found in the audit.
UPDATE escrow_payment e
JOIN membership_seat s ON s.seat_id = e.seat_id
SET e.escrow_status = 'REFUNDED'
WHERE s.seat_status = 'REFUNDED' AND e.escrow_status <> 'REFUNDED';

UPDATE credit_event ce
JOIN (SELECT u.user_id, MIN(d.dispute_id) AS did
        FROM app_user u
        JOIN carpool_group g  ON g.host_id = u.user_id
        JOIN membership_seat s ON s.group_id = g.group_id
        JOIN dispute d        ON d.seat_id = s.seat_id
       GROUP BY u.user_id) x ON x.user_id = ce.user_id
SET ce.ref_dispute_id = x.did
WHERE ce.reason = 'DISPUTE_LOST' AND ce.ref_dispute_id IS NULL;
